    # If not provided and model not ollama, base_url must not be added
    ("base_url" not in OLD.OLD_kwargs and "ollama" not in (model_id or "").lower() and "base_url" not in result)
))
@icontract.ensure(lambda OLD, result: ("api_key" not in result) or (isinstance(result.get("api_key"), str) and result.get("api_key") != ""))
